// Matched FP8 projections (fp8_block.h). The arithmetic is crit's fp8_block_device.cuh, operation for operation: one
// e4m3 m16n8k32 MMA with a zero accumulator per 32-element block, one rounded scale product and one FMA per block on
// lane b % 16, the halving tree, post. Explicit round-to-nearest intrinsics keep the compiler from contracting anything.
// The block MMA, the step, the tree's fold and the scale decoders are crit's kernel core blocks (blockscaled_mma.cuh,
// reduce.cuh, formats.cuh), shared by every structure here.
//
// Knobs (kernel.json; crit_tuning.h, generated by crit's kernel build, picks them per shape and token count): the decode
// rows' WARPS (warps a CTA, the 16 lanes split over them), AHEAD (rounds of loads in flight) and STREAM (weight codes
// read with L1::no_allocate); the prompt GEMM's WARPS (16 rows each a CTA), TILES (n-tiles of 8 tokens a warp pass) and
// UNROLL (the block loop's unroll, 0 the compiler's choice). None changes an output's order: every lane sums its
// blocks in increasing order and the tree is fixed, whichever warp or pass computes it.
#include "fp8_block.h"
#if __has_include("crit_tuning.h")
#include "crit_tuning.h"
#else
// Built outside crit's kernel build (tests/fp8_block_tests.cu with plain nvcc): the default knobs only.
#define CRIT_CONFIGS_rows(X) X(0, 16, 2, 0)
#define CRIT_CONFIGS_gemm(X) X(0, 8, 4, 0)
#define CRIT_CONFIGS_gemm_staged(X) X(0, 128, 64, 4, 2, 2, 1, 4)
#define CRIT_CONFIGS_gemm_native(X) X(0, 128, 128, 2, 4, 64, 3, 8, 0)
#define CRIT_CONFIGS_gemm_native_channel(X) X(0, 128, 128, 2, 4, 128, 3, 8, 1)
#define CRIT_CONFIGS_gemm_native_blocks(X) X(0, 128, 128, 2, 4, 128, 2, 8, 1)
static inline int crit_lookup_rows(long long, long long, int) { return 0; }
static inline int crit_lookup_gemm(long long, long long, int) { return 0; }
static inline int crit_lookup_gemm_staged(long long, long long, int) { return 0; }
static inline int crit_lookup_gemm_native(long long, long long, int) { return 0; }
static inline int crit_lookup_gemm_native_channel(long long, long long, int) { return 0; }
static inline int crit_lookup_gemm_native_blocks(long long, long long, int) { return 0; }
#endif

#include "crit_kcore/blockscaled_mma.cuh"
#include "crit_kcore/blockscaled_order.cuh"
#include "crit_kcore/blockscaled_stage.cuh"
#include "crit_kcore/declared_rows.cuh"
#include "crit_kcore/formats.cuh"
#include "crit_kcore/gemm_epilogue.cuh"
#include "crit_kcore/mma_fp8.cuh"
#include "crit_kcore/tile.cuh"

#include <cuda_bf16.h>
#include <cuda_fp8.h>
#include <cstdint>

namespace crit::techniques::fp8_block {
namespace {

namespace kc = crit::kcore;
namespace bs = crit::kcore::blockscaled;

constexpr int kBlock = 32, kLanes = 16;

// Bytes 8q .. 8q + 7 of block b of one row or token (crit's fragment order).
__device__ inline uint2 fragment(const std::uint8_t* row, int b, int q) {
    return *reinterpret_cast<const uint2*>(row + kBlock * b + 8 * q);
}

// The same bytes of a weight row, read past L1 when STREAM (a decode reads each weight byte once).
template<int STREAM>
__device__ inline uint2 weight_fragment(const std::uint8_t* row, int b, int q) {
    if constexpr(STREAM) {
        uint2 v;
        asm volatile("ld.global.nc.L1::no_allocate.v2.u32 {%0, %1}, [%2];"
                     : "=r"(v.x), "=r"(v.y) : "l"(row + kBlock * b + 8 * q));
        return v;
    } else {
        return fragment(row, b, q);
    }
}

// A weight scale k of a matrix's scale row: FP32, or an E8M0 byte (2^(e - 127); 0 is 2^-127, 255 NaN).
__device__ inline float weight_scale(const std::uint8_t* row, int k, int e8m0) {
    return e8m0 ? kc::e8m0_value(row[k]) : reinterpret_cast<const float*>(row)[k];
}

// ---------------------------------------------------------------------------------------------------- decode rows

// The rows are the kernel core's declared FP8 rows (declared_rows.cuh's fp8_rows_kernel, on multiply.cuh's
// DeclaredFp8 and ScaleGrid): 16 rows a CTA, warp w the lanes w, w + WARPS, ..., AHEAD rounds of loads in flight, one
// thread an output reducing its 16 lanes by the halving tree; the operations this file's rows kernel ran, so the same
// bits.

// ---------------------------------------------------------------------------------------------------- prompt GEMM

// A warp computes 16 rows x 8 kTiles tokens (kTiles n-tiles sharing the A fragment; 4 by default, 32 tokens) per pass,
// lane by lane in kLaneOrder16: lane j's blocks j, j + 16, ... in order, each block's sum from the tensor cores and the
// FP32 step on the CUDA cores, then the lane folded into the tree. Token tiles spread over grid.z. kUnroll unrolls the
// block loop that many times (0: as the compiler chooses); the sums keep their order.
template<int kGemmWarps, int kTiles, int kUnroll>
__global__ void __launch_bounds__(32 * kGemmWarps) gemm_kernel(const Matrix* matrices, const GemmJob* jobs, Acts acts,
                                                               float* out, int out_ld) {
    constexpr int kGemmRows = 16 * kGemmWarps, kGemmTokens = 8 * kTiles;
    const GemmJob job = jobs[blockIdx.y];
    const Matrix m = matrices[job.matrix];
    const int warp = int(threadIdx.x) / 32, lane = int(threadIdx.x) % 32, g = lane / 4, q = lane % 4;
    const int row0 = int(blockIdx.x) * kGemmRows + warp * 16;
    if(row0 >= m.rows || job.count <= 0) return;
    const bool live_a = row0 + g < m.rows, live_b = row0 + g + 8 < m.rows;
    const int ra = live_a ? row0 + g : m.rows - 1, rb = live_b ? row0 + g + 8 : m.rows - 1;
    const std::uint8_t* wa = m.codes + std::size_t(ra) * std::size_t(m.cols);
    const std::uint8_t* wb = m.codes + std::size_t(rb) * std::size_t(m.cols);
    const std::size_t sld = std::size_t(m.cols / m.scale_k) * (m.scale_e8m0 ? 1u : 4u);
    const std::uint8_t* wsa = static_cast<const std::uint8_t*>(m.scales) + std::size_t(ra / m.scale_rows) * sld;
    const std::uint8_t* wsb = static_cast<const std::uint8_t*>(m.scales) + std::size_t(rb / m.scale_rows) * sld;
    const int blocks = m.cols / kBlock, last = job.first + job.count - 1;
    for(int tile = kGemmTokens * int(blockIdx.z); tile < job.count; tile += kGemmTokens * int(gridDim.z)) {
        const std::uint8_t* xg[kTiles];
        const float* xs[kTiles][2];
#pragma unroll
        for(int n = 0; n < kTiles; ++n) {
            const int t = min(job.first + tile + 8 * n + g, last);
            xg[n] = acts.codes + std::size_t(t) * std::size_t(acts.ld);
#pragma unroll
            for(int c = 0; c < 2; ++c)
                xs[n][c] = acts.scales + std::size_t(min(job.first + tile + 8 * n + 2 * q + c, last)) * std::size_t(acts.lds);
        }
        float x[4 * kTiles][4];
#pragma unroll
        for(int at = 0; at < kLanes; ++at) {
            const int j = kc::kLaneOrder16[at];
            float acc[4 * kTiles];
#pragma unroll
            for(int o = 0; o < 4 * kTiles; ++o) acc[o] = 0.0f;
            auto block = [&](int b) {
                const uint2 a_g = fragment(wa, b, q), a_g8 = fragment(wb, b, q);
                const int wk = b * kBlock / m.scale_k, xk = b * kBlock / acts.group;
                const float w0 = weight_scale(wsa, wk, m.scale_e8m0), w1 = weight_scale(wsb, wk, m.scale_e8m0);
#pragma unroll
                for(int n = 0; n < kTiles; ++n) {
                    float d[4];
                    bs::block_sum_e4m3(a_g, a_g8, fragment(xg[n], b, q), d);
                    const float a0 = xs[n][0][xk], a1 = xs[n][1][xk];
                    acc[4 * n + 0] = bs::step(d[0], w0, a0, acc[4 * n + 0]);
                    acc[4 * n + 1] = bs::step(d[1], w0, a1, acc[4 * n + 1]);
                    acc[4 * n + 2] = bs::step(d[2], w1, a0, acc[4 * n + 2]);
                    acc[4 * n + 3] = bs::step(d[3], w1, a1, acc[4 * n + 3]);
                }
            };
            if constexpr(kUnroll == 0) {
                for(int b = j; b < blocks; b += kLanes) block(b);
            } else {
#pragma unroll kUnroll
                for(int b = j; b < blocks; b += kLanes) block(b);
            }
#pragma unroll
            for(int o = 0; o < 4 * kTiles; ++o) kc::fold16(at, acc[o], x[o]);
        }
#pragma unroll
        for(int n = 0; n < kTiles; ++n)
#pragma unroll
            for(int o = 0; o < 4; ++o) {
                const int t = tile + 8 * n + 2 * q + o % 2;
                if(t < job.count && (o / 2 ? live_b : live_a))
                    out[std::size_t(job.first + t) * std::size_t(out_ld) + std::size_t(o / 2 ? row0 + g + 8 : row0 + g)] =
                        __fmul_rn(x[4 * n + o][0], m.post);
            }
    }
}

// ---------------------------------------------------------------------------------------------------- staged GEMM

// The prompt GEMM with shared-memory staging (structure gemm-staged), from crit's kernel core blocks. A CTA computes
// BM weight rows x BN tokens. The blocks are visited lane by lane in the tree's order, G lanes and RUN blocks of each a
// visit (blockscaled_order.cuh's GroupVisits); each visit is one stage of a STAGES-deep cp.async ring (load.cuh): its
// blocks' 32 bytes of every row and token, the weight scales' words and the token scales, all asynchronous, the
// multistage mainloop CUTLASS uses (BSD-3-Clause; the mechanism, no code). One stage ahead of the MMAs the CTA decodes
// the stage's weight scales to FP32 (pair_slot order); then a warp computes BM / WM rows x BN / WN tokens: one e4m3
// m16n8k32 MMA with a zero accumulator per 16 x 8 tile and block (block_sum_e4m3, crit's fragment order), the declared
// step on its lane, the G lanes folded into the tree when their last block is done. Every output has the declared
// order's bits: the same as `gemm` and `rows`, whatever the knobs.
template<int BM, int BN, int WM, int WN, int G, int RUN, int STAGES>
struct Staged {
    static_assert(STAGES >= 3, "a stage is decoded one iteration before its MMAs");
    static constexpr int kThreads = 32 * WM * WN, kWarpRows = BM / WM, kWarpTokens = BN / WN;
    static constexpr int kMT = kWarpRows / 16, kNT = kWarpTokens / 8, kOut = 4 * kMT * kNT;
    static_assert(kMT >= 1 && kNT >= 1 && kWarpRows % 16 == 0 && kWarpTokens % 8 == 0, "warp tiles of 16 x 8");
    static constexpr int kRowsPer = (BM + kThreads - 1) / kThreads, kTokensPer = (BN + kThreads - 1) / kThreads;
    static constexpr int kCopies = 2 * (BM + BN), kCopiesPer = (kCopies + kThreads - 1) / kThreads;
    // A block of a stage: weight rows [BM][32], tokens [BN][32], the weight scales' words [BM] as copied, the token
    // scales [BN], the weight scales decoded [BM] (pair_slot).
    static constexpr int kA = 0, kB = BM * kBlock, kWraw = kB + BN * kBlock, kAs = kWraw + 4 * BM, kWs = kAs + 4 * BN;
    static constexpr int kSub = kWs + 4 * BM, kStage = G * RUN * kSub, kSmem = STAGES * kStage;
    // CTAs an SM can hold by registers (the launch bound): an output holds G running lanes and the partial sums still
    // needed (5 registers, 6 with G = 4), plus about 48 a thread of fragments and addresses.
    static constexpr int kRegs = (kOut * (G == 4 ? 6 : 5) + 48 + 7) / 8 * 8;
    static constexpr int kFit = 65536 / (kThreads * kRegs), kMinBlocks = kFit < 1 ? 1 : kFit > 4 ? 4 : kFit;
};

template<int BM, int BN, int WM, int WN, int G, int RUN, int STAGES>
__global__ void __launch_bounds__(32 * WM * WN, (Staged<BM, BN, WM, WN, G, RUN, STAGES>::kMinBlocks))
    staged_kernel(const Matrix* matrices, const GemmJob* jobs, Acts acts, float* out, int out_ld) {
    using S = Staged<BM, BN, WM, WN, G, RUN, STAGES>;
    using Visits = bs::GroupVisits<G, RUN>;
    extern __shared__ __align__(16) unsigned char smem[];
    const GemmJob job = jobs[blockIdx.y];
    const Matrix m = matrices[job.matrix];
    const int row0 = int(blockIdx.x) * BM;
    if(row0 >= m.rows || job.count <= 0) return;
    const int tid = int(threadIdx.x), warp = tid / 32, lane = tid % 32, g = lane / 4, q = lane % 4;
    const int wr = (warp / WN) * S::kWarpRows, wt = (warp % WN) * S::kWarpTokens;
    const int blocks = m.cols / kBlock, last = job.first + job.count - 1;
    const std::size_t sld = std::size_t(m.cols / m.scale_k) * (m.scale_e8m0 ? 1u : 4u);
    const std::uint8_t* wscales = static_cast<const std::uint8_t*>(m.scales);
    // Block -> scale column divisions as multiply-highs (exact for blocks and divisors below 2^16).
    const unsigned w_div = unsigned(m.scale_k / kBlock), a_div = unsigned(acts.group / kBlock);
    const unsigned w_mul = w_div > 1 ? unsigned((0x100000000ull + w_div - 1) / w_div) : 0u;
    const unsigned a_mul = a_div > 1 ? unsigned((0x100000000ull + a_div - 1) / a_div) : 0u;
    const unsigned w_size = m.scale_e8m0 ? 1u : 4u;

    for(int tile = BN * int(blockIdx.z); tile < job.count; tile += BN * int(gridDim.z)) {
        // This thread's copies: 16-byte pieces of rows and tokens, its weight rows' and tokens' scale rows.
        const std::uint8_t* copy_src[S::kCopiesPer];
        int copy_dst[S::kCopiesPer];
#pragma unroll
        for(int u = 0; u < S::kCopiesPer; ++u) {
            const int i = tid + u * S::kThreads, r = i / 2, h = i % 2;
            if(r < BM) {
                copy_src[u] = m.codes + std::size_t(min(row0 + r, m.rows - 1)) * std::size_t(m.cols) + 16 * h;
                copy_dst[u] = S::kA + r * kBlock + 16 * h;
            } else {
                copy_src[u] = acts.codes + std::size_t(min(job.first + tile + (r - BM), last)) * std::size_t(acts.ld) +
                              16 * h;
                copy_dst[u] = S::kB + (r - BM) * kBlock + 16 * h;
            }
        }
        const std::uint8_t* w_row[S::kRowsPer];
        const float* a_row[S::kTokensPer];
#pragma unroll
        for(int u = 0; u < S::kRowsPer; ++u)
            w_row[u] = wscales + std::size_t(min(row0 + tid + u * S::kThreads, m.rows - 1) / m.scale_rows) * sld;
#pragma unroll
        for(int u = 0; u < S::kTokensPer; ++u)
            a_row[u] = acts.scales + std::size_t(min(job.first + tile + tid + u * S::kThreads, last)) *
                                         std::size_t(acts.lds);
        auto w_scale_at = [&](int u, int b) {
            return w_row[u] + std::size_t(w_size) * (w_div > 1 ? __umulhi(unsigned(b), w_mul) : unsigned(b));
        };
        // A visit's copies into stage `slot` (a lane without a block copies the first lane's: never used).
        auto issue = [&](int slot, const Visits& it) {
#pragma unroll
            for(int i = 0; i < G * RUN; ++i) {
                const int s = i % G, r = i / G;
                const int b = it.block(s, r) >= 0 ? it.block(s, r) : it.block(0);
                unsigned char* sub = smem + slot * S::kStage + i * S::kSub;
#pragma unroll
                for(int u = 0; u < S::kCopiesPer; ++u)
                    if(S::kCopies % S::kThreads == 0 || tid + u * S::kThreads < S::kCopies)
                        kc::cp_async16(sub + copy_dst[u], copy_src[u] + std::size_t(kBlock) * std::size_t(b));
#pragma unroll
                for(int u = 0; u < S::kRowsPer; ++u) {
                    const int r = tid + u * S::kThreads;
                    if(BM % S::kThreads == 0 || r < BM) {   // the word holding the scale (E8M0 bytes: any alignment)
                        const std::uintptr_t at = reinterpret_cast<std::uintptr_t>(w_scale_at(u, b));
                        kc::cp_async_ca<4>(sub + S::kWraw + 4 * r,
                                           reinterpret_cast<const void*>(at & ~std::uintptr_t(3)));
                    }
                }
                const int ak = a_div > 1 ? int(__umulhi(unsigned(b), a_mul)) : b;
#pragma unroll
                for(int u = 0; u < S::kTokensPer; ++u) {
                    const int r = tid + u * S::kThreads;
                    if(BN % S::kThreads == 0 || r < BN) kc::cp_async_ca<4>(sub + S::kAs + 4 * r, a_row[u] + ak);
                }
            }
        };
        // The weight scales of a landed stage to FP32, by the threads that copied them.
        auto decode = [&](int slot, const Visits& it) {
#pragma unroll
            for(int i = 0; i < G * RUN; ++i) {
                const int b = it.block(i % G, i / G);
                if(b < 0) continue;
                unsigned char* sub = smem + slot * S::kStage + i * S::kSub;
                float* ws = reinterpret_cast<float*>(sub + S::kWs);
#pragma unroll
                for(int u = 0; u < S::kRowsPer; ++u) {
                    const int r = tid + u * S::kThreads;
                    if(BM % S::kThreads == 0 || r < BM) {
                        const unsigned word = *reinterpret_cast<const unsigned*>(sub + S::kWraw + 4 * r);
                        const unsigned at = unsigned(reinterpret_cast<std::uintptr_t>(w_scale_at(u, b)) & 3u);
                        ws[bs::pair_slot(r)] = m.scale_e8m0 ? kc::e8m0_value(word >> (8 * at)) : __uint_as_float(word);
                    }
                }
            }
        };

        Visits producer(blocks), decoder(blocks);
#pragma unroll
        for(int s = 0; s < STAGES - 1; ++s) {
            if(!producer.done()) {
                issue(s, producer);
                producer.next();
            }
            kc::cp_async_commit();
        }
        kc::cp_async_wait<STAGES - 2>();
        __syncthreads();
        decode(0, decoder);
        decoder.next();

        float acc[G][S::kOut], x[S::kOut][4];
        int v = 0;
        // G lanes at a time in the tree's order: their blocks (a lane past the last block has none: the tree then
        // takes +0.0f), RUN of each a visit of the ring, then the lanes folded into the partial sums.
#pragma unroll
        for(int at = 0; at < 16; at += G) {
#pragma unroll
            for(int s = 0; s < G; ++s)
#pragma unroll
                for(int o = 0; o < S::kOut; ++o) acc[s][o] = 0.0f;
            const int count = Visits::count(at, blocks);
            for(int k0 = 0; k0 < count; k0 += RUN, ++v) {
                kc::cp_async_wait<STAGES - 3>();
                __syncthreads();
                if(!decoder.done()) {
                    decode((v + 1) % STAGES, decoder);
                    decoder.next();
                }
                if(!producer.done()) {
                    issue((v + STAGES - 1) % STAGES, producer);
                    producer.next();
                }
                kc::cp_async_commit();
                // One block of each lane at a time (not unrolled: the fragments of one in registers at once).
#pragma unroll 1
                for(int r = 0; r < RUN; ++r)
#pragma unroll
                for(int s = 0; s < G; ++s) {
                    if(bs::lane_at(at + s) + 16 * (k0 + r) >= blocks) continue;
                    const unsigned char* sub = smem + (v % STAGES) * S::kStage + (r * G + s) * S::kSub;
                    const float* ws = reinterpret_cast<const float*>(sub + S::kWs);
                    const float* as = reinterpret_cast<const float*>(sub + S::kAs);
                    uint2 fa[S::kMT][2], fb[S::kNT];
                    float2 w[S::kMT], a[S::kNT];
#pragma unroll
                    for(int mt = 0; mt < S::kMT; ++mt) {
                        const int r = wr + 16 * mt + g;
                        fa[mt][0] = *reinterpret_cast<const uint2*>(sub + S::kA + r * kBlock + 8 * q);
                        fa[mt][1] = *reinterpret_cast<const uint2*>(sub + S::kA + (r + 8) * kBlock + 8 * q);
                        w[mt] = *reinterpret_cast<const float2*>(ws + bs::pair_slot(r));
                    }
#pragma unroll
                    for(int nt = 0; nt < S::kNT; ++nt) {
                        fb[nt] = *reinterpret_cast<const uint2*>(sub + S::kB + (wt + 8 * nt + g) * kBlock + 8 * q);
                        a[nt] = *reinterpret_cast<const float2*>(as + wt + 8 * nt + 2 * q);
                    }
                    // The block's MMAs first, then their steps: the sums of all tiles in flight together.
                    float d[S::kMT][S::kNT][4];
#pragma unroll
                    for(int mt = 0; mt < S::kMT; ++mt)
#pragma unroll
                        for(int nt = 0; nt < S::kNT; ++nt) bs::block_sum_e4m3(fa[mt][0], fa[mt][1], fb[nt], d[mt][nt]);
#pragma unroll
                    for(int mt = 0; mt < S::kMT; ++mt)
#pragma unroll
                        for(int nt = 0; nt < S::kNT; ++nt) {
                            float* c = acc[s] + 4 * (mt * S::kNT + nt);
                            c[0] = bs::step(d[mt][nt][0], w[mt].x, a[nt].x, c[0]);
                            c[1] = bs::step(d[mt][nt][1], w[mt].x, a[nt].y, c[1]);
                            c[2] = bs::step(d[mt][nt][2], w[mt].y, a[nt].x, c[2]);
                            c[3] = bs::step(d[mt][nt][3], w[mt].y, a[nt].y, c[3]);
                        }
                }
            }
#pragma unroll
            for(int s = 0; s < G; ++s)
#pragma unroll
                for(int o = 0; o < S::kOut; ++o) kc::fold16(at + s, acc[s][o], x[o]);
        }
#pragma unroll
        for(int mt = 0; mt < S::kMT; ++mt)
#pragma unroll
            for(int nt = 0; nt < S::kNT; ++nt)
#pragma unroll
                for(int o = 0; o < 4; ++o) {
                    const int r = row0 + wr + 16 * mt + g + 8 * (o / 2), t = tile + wt + 8 * nt + 2 * q + o % 2;
                    if(r < m.rows && t < job.count)
                        out[std::size_t(job.first + t) * std::size_t(out_ld) + std::size_t(r)] =
                            __fmul_rn(x[4 * (mt * S::kNT + nt) + o][0], m.post);
                }
        __syncthreads();   // the next token tile's prologue refills the stages
    }
}

// ---------------------------------------------------------------------------------------------------- native GEMM

// The prompt GEMM accumulated in the tensor cores (structure gemm-native): not the declared order. A CTA computes TM
// tokens x TN weight rows (the tokens the MMA's A operand, so a lane's accumulator pair is two adjacent outputs of a
// token), a warp TM / WM x TN / WN, the K loop in BK-byte stages of a STAGES-deep cp.async ring of swizzled tiles
// (kernel core tile.cuh: KTileCopy, ldsm_a, ldsm_b2, copy_rows, store_tile), persistent CTAs over the tiles: the
// multistage mainloop and tile scheduling of CUTLASS (BSD-3-Clause; the mechanisms and the shared-memory layouts,
// written anew). Two arithmetic paths, chosen by the call (enqueue_gemm_native's mx):
//   native  (sm_120a; MXFP8 throughout: E8M0 weight scales per 32 of one row, activation scales MXFP8's powers of two
//           per 32, cols a multiple of 128): kind::mxf8f6f4 block-scaled MMAs (mma.cuh's mma_mxf8_e4m3_m16n8k32), the
//           tensor core applying both scales and summing every block into its FP32 accumulator;
//   generic (every other scale layout, and every architecture without block-scaled MMAs): one e4m3 MMA from a zero
//           accumulator a 32-element block (the products' sum), then acc += sum * (weight scale * activation scale)
//           on the CUDA cores; the stage's scales copied as words and decoded to FP32 in shared memory.
// An output's sum depends on the CTA tile (which blocks the tensor core sums together, in its own order), so its bits
// may change with the knobs and the token count: row_invariant false. Within 1e-5 of the FP64 product's magnitude
// (the block-scaled MMA's own block sum is not FP32 round to nearest), 2e-6 on the generic path.
template<int TM, int TN, int WM, int WN, int BK, int STAGES, int GROUP>
struct Native {
    static constexpr int kThreads = 32 * WM * WN, kWTM = TM / WM, kWTN = TN / WN;
    static constexpr int kMT = kWTM / 16, kNT = kWTN / 8, kKB = BK / 32;
    static_assert(kWTM % 16 == 0 && kWTN % 16 == 0 && kMT >= 1, "warp tiles of whole 16-token, 16-row tiles");
    static_assert(BK == 64 || BK == 128, "64 or 128 bytes of K a stage");
    static_assert(STAGES >= 2, "a ring of two stages or more");
    // A stage: tokens' codes [TM][BK] and weight codes [TN][BK] (tile.cuh's swizzled tiles), then the scales: native,
    // token scales FP32 [TM][kKB] and one E8M0 word a weight row [TN]; generic, FP32 [TM][kKB] then [TN][kKB].
    static constexpr int kA = 0, kB = TM * BK, kS = kB + TN * BK;
    static constexpr int kNativeS = TM * kKB * 4 + TN * 4, kGenericS = (TM + TN) * kKB * 4;
    static constexpr int kStage = (kS + (kGenericS > kNativeS ? kGenericS : kNativeS) + 127) / 128 * 128;
    static constexpr int kSmem = STAGES * kStage;
    // Rows of the accumulator tile the epilogue stages in shared memory at a time (tile.cuh's store_tile).
    static constexpr int kChunk = crit::kcore::tile::store_chunk(TM, TN, kSmem);
    static_assert(kChunk * (TN + 4) * 4 <= kSmem, "the epilogue's 16 rows within the ring's shared memory");
    static constexpr int kItems = ((TM + TN) * kKB + kThreads - 1) / kThreads;   // a thread's generic scale words
};

// Four exponents of positive FP32 powers of two (bits 23..30) as E8M0 bytes of a word, the first in the low byte.
__device__ __forceinline__ uint32_t e8m0_word(uint4 f) {
    return __byte_perm(__byte_perm(f.x << 1, f.y << 1, 0x0073u), __byte_perm(f.z << 1, f.w << 1, 0x0073u), 0x5410u);
}

// A CTA's tiles of one job, persistent: tiles blockIdx.x, + gridDim.x, ... in tile_of's grouped order. Each tile's
// first STAGES - 1 stages are issued before the previous tile's epilogue (EPI 0: the accumulators stored from
// registers while the next tile's copies fly) or right after it (EPI 1: through shared memory, tile.cuh's store_tile,
// whole rows a store).
template<class C, bool NATIVE, class OUT, int TM, int TN, int WM, int BK, int STAGES, int EPI>
__device__ __forceinline__ void native_tiles(const Matrix& m, const Acts& acts, const GemmJob& job, int tiles_m,
                                             int tiles_n, int group, unsigned char* smem, OUT* out, int out_ld) {
    namespace kt = crit::kcore::tile;
    constexpr int T = C::kThreads, MT = C::kMT, NT = C::kNT, KB = C::kKB;
    const int tid = int(threadIdx.x), warp = tid / 32, lane = tid % 32, gid = lane >> 2, tig = lane & 3;
    const int wm0 = (warp % WM) * C::kWTM, wn0 = (warp / WM) * C::kWTN;
    const int K = m.cols, KT = (K + BK - 1) / BK, total = tiles_m * tiles_n;
    const unsigned char* w_scales = static_cast<const unsigned char*>(m.scales);
    const int w_ld = K / m.scale_k;

    struct Tile {
        int n0, tokens, rows;
        std::size_t token0;
        kt::KTileCopy<TM, BK, T> a;
        kt::KTileCopy<TN, BK, T> b;
        const unsigned char* a_scales;   // native: the tile's first token's scale row
        int a_width;
    };
    auto set = [&](Tile& s, int linear) {
        int tm, tn;
        kt::tile_of(linear, tiles_m, tiles_n, group, tm, tn);
        s.n0 = tn * TN;
        s.tokens = min(TM, job.count - tm * TM);
        s.rows = min(TN, m.rows - s.n0);
        s.token0 = std::size_t(job.first + tm * TM);
        s.a.init(acts.codes + s.token0 * std::size_t(acts.ld), std::size_t(acts.ld), s.tokens, tid);
        s.b.init(m.codes + std::size_t(s.n0) * std::size_t(K), std::size_t(K), s.rows, tid);
        s.a_scales = reinterpret_cast<const unsigned char*>(acts.scales + s.token0 * std::size_t(acts.lds));
        s.a_width = kt::row_copy_width(s.a_scales, std::size_t(acts.lds) * 4, KB * 4);
    };
    // Generic: scale word i of [TM][KB] then [TN][KB] is thread i % T's; its source (floats for FP32, bytes for E8M0).
    auto item = [&](const Tile& s, int i, int k0, bool& is_a, bool& ok) -> std::size_t {
        is_a = i < TM * KB;
        const int j = is_a ? i : i - TM * KB, row = j / KB, k = k0 + 32 * (j % KB);
        ok = (is_a ? row < s.tokens : row < s.rows) && k < K;
        if(!ok) return 0;
        return is_a ? (s.token0 + std::size_t(row)) * std::size_t(acts.lds) + std::size_t(k / acts.group)
                    : std::size_t((s.n0 + row) / m.scale_rows) * std::size_t(w_ld) + std::size_t(k / m.scale_k);
    };
    auto issue = [&](const Tile& s, int k_tile) {
        unsigned char* stage = smem + (k_tile % STAGES) * C::kStage;
        const int k0 = k_tile * BK;
        s.a.issue(stage + C::kA, k0, K);
        s.b.issue(stage + C::kB, k0, K);
        if constexpr(NATIVE) {
            // the stage's token scales by row copies, the weight rows' E8M0 word (4 blocks) by 4-byte copies
            kt::copy_rows<TM, KB * 4, T>(stage + C::kS, s.a_scales, std::size_t(acts.lds) * 4, s.tokens,
                                         (k0 / 32) * 4, acts.lds * 4, s.a_width, tid);
            kt::copy_rows<TN, 4, T>(stage + C::kS + TM * KB * 4, w_scales + std::size_t(s.n0) * std::size_t(K / 32),
                                    std::size_t(K / 32), s.rows, (k0 / 32) & ~3, K / 32, 4, tid);
        } else {
            float* f = reinterpret_cast<float*>(stage + C::kS);
#pragma unroll
            for(int u = 0; u < C::kItems; ++u) {
                const int i = tid + u * T;
                if(i >= (TM + TN) * KB) continue;
                bool is_a, ok;
                const std::size_t o = item(s, i, k0, is_a, ok);
                const void* src = is_a ? static_cast<const void*>(acts.scales + o)
                                  : m.scale_e8m0 ? static_cast<const void*>(w_scales + (o & ~std::size_t(3)))
                                                 : static_cast<const void*>(static_cast<const float*>(m.scales) + o);
                kc::cp_async_ca<4>(f + i, ok ? src : m.scales, ok);
            }
        }
    };
    // Generic: a landed stage's E8M0 words to FP32, in place, by the threads that copied them.
    auto prepare = [&](const Tile& s, int k_tile) {
        if constexpr(!NATIVE) {
            if(!m.scale_e8m0) return;
            float* f = reinterpret_cast<float*>(smem + (k_tile % STAGES) * C::kStage + C::kS);
            const int k0 = k_tile * BK;
#pragma unroll
            for(int u = 0; u < C::kItems; ++u) {
                const int i = tid + u * T;
                if(i < TM * KB || i >= (TM + TN) * KB) continue;
                bool is_a, ok;
                const std::size_t o = item(s, i, k0, is_a, ok);
                f[i] = kc::e8m0_value(__float_as_uint(f[i]) >> (8 * (o & 3)));
            }
        }
    };
    auto prologue = [&](const Tile& s) {
#pragma unroll
        for(int st = 0; st < STAGES - 1; ++st) {
            if(st < KT) issue(s, st);
            kc::cp_async_commit();
        }
    };
    auto fragments = [&](const unsigned char* stage, int ks, uint32_t (&a)[MT][4], uint32_t (&b)[NT][2]) {
#pragma unroll
        for(int i = 0; i < MT; ++i) kt::ldsm_a<BK>(stage + C::kA, wm0 + 16 * i, ks, lane, a[i]);
#pragma unroll
        for(int j = 0; j < NT; j += 2) {
            uint32_t four[4];
            kt::ldsm_b2<BK>(stage + C::kB, wn0 + 8 * j, ks, lane, four);
            b[j][0] = four[0], b[j][1] = four[1], b[j + 1][0] = four[2], b[j + 1][1] = four[3];
        }
    };
    auto scales = [&](const unsigned char* stage, int k_tile, uint32_t (&sa)[MT], uint32_t (&sb)[NT]) {
        const int shift = 8 * ((k_tile * BK / 32) & 3);
#pragma unroll
        for(int i = 0; i < MT; ++i) {
            const float* f = reinterpret_cast<const float*>(stage + C::kS) + (wm0 + 16 * i + gid + 8 * (tig & 1)) * KB;
            if constexpr(KB == 4) {
                sa[i] = e8m0_word(*reinterpret_cast<const uint4*>(f));
            } else {
                const uint2 two = *reinterpret_cast<const uint2*>(f);
                sa[i] = e8m0_word(make_uint4(two.x, two.y, 0u, 0u));
            }
        }
#pragma unroll
        for(int j = 0; j < NT; ++j)
            sb[j] = reinterpret_cast<const uint32_t*>(stage + C::kS + TM * KB * 4)[wn0 + 8 * j + gid] >> shift;
    };

    int linear = int(blockIdx.x);
    Tile cur;
    set(cur, linear);
    prologue(cur);
    for(;;) {
        float acc[MT][NT][4];
#pragma unroll
        for(int i = 0; i < MT; ++i)
#pragma unroll
            for(int j = 0; j < NT; ++j) acc[i][j][0] = acc[i][j][1] = acc[i][j][2] = acc[i][j][3] = 0.0f;
        if constexpr(NATIVE) {
            // CUTLASS's multistage order (BSD-3-Clause; the mechanism): a k-step's fragments are read while the
            // previous k-step's MMAs run, and the next stage's wait and barrier come before the last k-step of a stage,
            // so its MMAs cover the first reads of the next stage; a stage's copies are issued after its first k-step.
            uint32_t a[2][MT][4], b[2][NT][2], sa[MT], sb[NT], na[MT], nb[NT];
            kc::cp_async_wait<STAGES - 2>();
            __syncthreads();
            scales(smem, 0, sa, sb);
            fragments(smem, 0, a[0], b[0]);
            for(int k_tile = 0; k_tile < KT; ++k_tile) {
                const unsigned char* stage = smem + (k_tile % STAGES) * C::kStage;
                const unsigned char* next = smem + ((k_tile + 1) % STAGES) * C::kStage;
#pragma unroll
                for(int ks = 0; ks < KB; ++ks) {
                    if(ks == KB - 1) {
                        kc::cp_async_wait<STAGES - 2>();
                        __syncthreads();
                        if(k_tile + 1 < KT) {
                            scales(next, k_tile + 1, na, nb);
                            fragments(next, 0, a[(ks + 1) & 1], b[(ks + 1) & 1]);
                        }
                    } else {
                        fragments(stage, ks + 1, a[(ks + 1) & 1], b[(ks + 1) & 1]);
                    }
                    if(ks == 0) {
                        if(k_tile + STAGES - 1 < KT) issue(cur, k_tile + STAGES - 1);
                        kc::cp_async_commit();
                    }
#pragma unroll
                    for(int i = 0; i < MT; ++i)
#pragma unroll
                        for(int j = 0; j < NT; ++j)
                            kc::mma_mxf8_e4m3_m16n8k32(acc[i][j], a[ks & 1][i][0], a[ks & 1][i][1], a[ks & 1][i][2],
                                                       a[ks & 1][i][3], b[ks & 1][j][0], b[ks & 1][j][1],
                                                       sa[i] >> (8 * ks), sb[j] >> (8 * ks));
                }
#pragma unroll
                for(int i = 0; i < MT; ++i) sa[i] = na[i];
#pragma unroll
                for(int j = 0; j < NT; ++j) sb[j] = nb[j];
            }
        } else {
            for(int k_tile = 0; k_tile < KT; ++k_tile) {
                kc::cp_async_wait<STAGES - 2>();
                prepare(cur, k_tile);
                __syncthreads();
                if(k_tile + STAGES - 1 < KT) issue(cur, k_tile + STAGES - 1);
                kc::cp_async_commit();
                const unsigned char* stage = smem + (k_tile % STAGES) * C::kStage;
                const float* f = reinterpret_cast<const float*>(stage + C::kS);
#pragma unroll
                for(int ks = 0; ks < KB; ++ks) {
                    uint32_t a[MT][4], b[NT][2];
                    fragments(stage, ks, a, b);
                    float xa[MT][2], xw[NT][2];
#pragma unroll
                    for(int i = 0; i < MT; ++i) {
                        xa[i][0] = f[(wm0 + 16 * i + gid) * KB + ks];
                        xa[i][1] = f[(wm0 + 16 * i + gid + 8) * KB + ks];
                    }
#pragma unroll
                    for(int j = 0; j < NT; ++j) {
                        xw[j][0] = f[(TM + wn0 + 8 * j + 2 * tig) * KB + ks];
                        xw[j][1] = f[(TM + wn0 + 8 * j + 2 * tig + 1) * KB + ks];
                    }
#pragma unroll
                    for(int i = 0; i < MT; ++i)
#pragma unroll
                        for(int j = 0; j < NT; ++j) {
                            float d[4];
                            kc::mma_e4m3_m16n8k32_zero(d, a[i][0], a[i][1], a[i][2], a[i][3], b[j][0], b[j][1]);
                            acc[i][j][0] = fmaf(d[0], xa[i][0] * xw[j][0], acc[i][j][0]);
                            acc[i][j][1] = fmaf(d[1], xa[i][0] * xw[j][1], acc[i][j][1]);
                            acc[i][j][2] = fmaf(d[2], xa[i][1] * xw[j][0], acc[i][j][2]);
                            acc[i][j][3] = fmaf(d[3], xa[i][1] * xw[j][1], acc[i][j][3]);
                        }
                }
            }
        }
        const int next = linear + int(gridDim.x);
        const bool more = next < total;
        Tile nx;
        OUT* tile_out = out + cur.token0 * std::size_t(out_ld) + std::size_t(cur.n0);
        // The epilogue: every output times post (gemm_epilogue.cuh's rank-1 store with unit token scales), rounded
        // once to the output type.
        float rs[MT][2], cs[NT][2];
#pragma unroll
        for(int i = 0; i < MT; ++i) rs[i][0] = rs[i][1] = 1.0f;
#pragma unroll
        for(int j = 0; j < NT; ++j) cs[j][0] = cs[j][1] = m.post;
        if constexpr(EPI == 0) {
            if(more) {
                __syncthreads();   // every warp's last reads of the ring are done
                set(nx, next);
                prologue(nx);
            }
            crit::kcore::gemm_out::store_scaled<OUT>(acc, rs, cs, wm0, wn0, lane, tile_out, std::size_t(out_ld),
                                                     cur.tokens, cur.rows);
        } else {
            constexpr int kChunk = crit::kcore::gemm_out::staged_chunk<OUT>(TM, TN, C::kSmem);
            kc::cp_async_wait<0>();
            crit::kcore::gemm_out::store_scaled_staged<OUT, TM, TN, MT, NT, kChunk, T>(
                acc, rs, cs, wm0, wn0, lane, reinterpret_cast<OUT*>(smem), tile_out, std::size_t(out_ld), cur.tokens,
                cur.rows, tid);
            if(more) {
                __syncthreads();   // every thread's reads of the staged rows are done
                set(nx, next);
                prologue(nx);
            }
        }
        if(!more) break;
        cur = nx;
        linear = next;
    }
    kc::cp_async_wait<0>();
}

// NATIVE: the caller states that the activation scales are MXFP8's and every matrix MXFP8 (native_ok); on sm_120a the
// kernel then holds the block-scaled path alone (a job that is not, contrary to the statement, gets NaN outputs: the
// generic path beside it would cost the native one registers). Elsewhere, and with NATIVE false, the generic path.
__device__ __forceinline__ bool native_ok(const Matrix& m, const Acts& acts) {
    return m.scale_e8m0 && m.scale_k == 32 && m.scale_rows == 1 && acts.group == 32 && m.cols % 128 == 0 &&
           reinterpret_cast<std::uintptr_t>(m.scales) % 4 == 0;
}

template<int TM, int TN, int WM, int WN, int BK, int STAGES, int GROUP, int EPI, bool NATIVE, class OUT>
__global__ void __launch_bounds__(32 * WM * WN, 1)
    native_kernel(const Matrix* matrices, const GemmJob* jobs, Acts acts, OUT* out, int out_ld) {
    using C = Native<TM, TN, WM, WN, BK, STAGES, GROUP>;
    extern __shared__ __align__(128) unsigned char native_smem[];
    const GemmJob job = jobs[blockIdx.y];
    const Matrix m = matrices[job.matrix];
    const int tiles_m = (job.count + TM - 1) / TM, tiles_n = (m.rows + TN - 1) / TN;
    if(job.count <= 0 || int(blockIdx.x) >= tiles_m * tiles_n) return;
    if constexpr(NATIVE && CRIT_KCORE_HAS_BLOCK_SCALED_MMA) {
        if(!native_ok(m, acts)) {
            if(blockIdx.x == 0)
                for(int i = int(threadIdx.x); i < job.count * m.rows; i += C::kThreads)
                    out[std::size_t(job.first + i / m.rows) * std::size_t(out_ld) + std::size_t(i % m.rows)] =
                        crit::kcore::gemm_out::round_to<OUT>(__int_as_float(0x7fc00000));
            return;
        }
        native_tiles<C, true, OUT, TM, TN, WM, BK, STAGES, EPI>(m, acts, job, tiles_m, tiles_n, GROUP, native_smem, out,
                                                           out_ld);
    } else {
        native_tiles<C, false, OUT, TM, TN, WM, BK, STAGES, EPI>(m, acts, job, tiles_m, tiles_n, GROUP, native_smem, out,
                                                            out_ld);
    }
}

// ---------------------------------------------------------------------------------------------------- channel GEMM

// The prompt GEMM of matrices whose scales do not change along K (structure gemm-native-channel): one FP32 scale a
// weight row (scale_k == cols, any scale_rows: per row, per block of rows, per tensor) and one scale a token (acts.lds
// 1), an FP8 checkpoint's per-channel W8A8. Every block of K sums in the tensor cores' FP32 accumulator (mma_fp8.cuh's
// fastest e4m3 MMA: on sm_120a the block-scaled kind with unit scales, twice the plain instruction's rate), and the
// epilogue applies token scale x (weight scale x post) and rounds once to FP32 or BF16 (gemm_epilogue.cuh): no scale
// enters the mainloop and no elementwise pass follows. The ring, fragments and persistent grouped order are the native
// GEMM's (tile.cuh); a stage holds codes only. Not the declared order, not row invariant.
template<int TM, int TN, int WM, int WN, int BK, int STAGES>
struct Channel {
    static constexpr int kThreads = 32 * WM * WN, kWTM = TM / WM, kWTN = TN / WN;
    static constexpr int kMT = kWTM / 16, kNT = kWTN / 8, kKB = BK / 32;
    static_assert(kWTM % 16 == 0 && kWTN % 16 == 0 && kMT >= 1, "warp tiles of whole 16-token, 16-row tiles");
    static_assert(BK == 64 || BK == 128, "64 or 128 bytes of K a stage");
    static_assert(STAGES >= 2, "a ring of two stages or more");
    static constexpr int kA = 0, kB = TM * BK, kStage = (TM + TN) * BK;
    static constexpr int kSmem = STAGES * kStage;
};

// FP32 weight scales constant along K and one activation scale a token: what the channel GEMM computes.
__device__ __forceinline__ bool channel_ok(const Matrix& m, const Acts& acts) {
    return m.scale_k == m.cols && m.scale_rows >= 1 && !m.scale_e8m0 && acts.lds == 1;
}

template<class C, class OUT, int TM, int TN, int WM, int BK, int STAGES, int EPI>
__device__ __forceinline__ void channel_tiles(const Matrix& m, const Acts& acts, const GemmJob& job, int tiles_m,
                                              int tiles_n, int group, unsigned char* smem, OUT* out, int out_ld) {
    namespace kt = crit::kcore::tile;
    namespace go = crit::kcore::gemm_out;
    constexpr int T = C::kThreads, MT = C::kMT, NT = C::kNT, KB = C::kKB;
    const int tid = int(threadIdx.x), warp = tid / 32, lane = tid % 32, gid = lane >> 2, tig = lane & 3;
    const int wm0 = (warp % WM) * C::kWTM, wn0 = (warp / WM) * C::kWTN;
    const int K = m.cols, KT = (K + BK - 1) / BK, total = tiles_m * tiles_n;

    struct Tile {
        int n0, tokens, rows;
        std::size_t token0;
        kt::KTileCopy<TM, BK, T> a;
        kt::KTileCopy<TN, BK, T> b;
    };
    auto set = [&](Tile& s, int linear) {
        int tm, tn;
        kt::tile_of(linear, tiles_m, tiles_n, group, tm, tn);
        s.n0 = tn * TN;
        s.tokens = min(TM, job.count - tm * TM);
        s.rows = min(TN, m.rows - s.n0);
        s.token0 = std::size_t(job.first + tm * TM);
        s.a.init(acts.codes + s.token0 * std::size_t(acts.ld), std::size_t(acts.ld), s.tokens, tid);
        s.b.init(m.codes + std::size_t(s.n0) * std::size_t(K), std::size_t(K), s.rows, tid);
    };
    auto issue = [&](const Tile& s, int k_tile) {
        unsigned char* stage = smem + (k_tile % STAGES) * C::kStage;
        s.a.issue(stage + C::kA, k_tile * BK, K);
        s.b.issue(stage + C::kB, k_tile * BK, K);
    };
    auto prologue = [&](const Tile& s) {
#pragma unroll
        for(int st = 0; st < STAGES - 1; ++st) {
            if(st < KT) issue(s, st);
            kc::cp_async_commit();
        }
    };
    auto fragments = [&](const unsigned char* stage, int ks, uint32_t (&a)[MT][4], uint32_t (&b)[NT][2]) {
#pragma unroll
        for(int i = 0; i < MT; ++i) kt::ldsm_a<BK>(stage + C::kA, wm0 + 16 * i, ks, lane, a[i]);
#pragma unroll
        for(int j = 0; j < NT; j += 2) {
            uint32_t four[4];
            kt::ldsm_b2<BK>(stage + C::kB, wn0 + 8 * j, ks, lane, four);
            b[j][0] = four[0], b[j][1] = four[1], b[j + 1][0] = four[2], b[j + 1][1] = four[3];
        }
    };

    const float* w_scales = static_cast<const float*>(m.scales);
    int linear = int(blockIdx.x);
    Tile cur;
    set(cur, linear);
    prologue(cur);
    for(;;) {
        float acc[MT][NT][4];
#pragma unroll
        for(int i = 0; i < MT; ++i)
#pragma unroll
            for(int j = 0; j < NT; ++j) acc[i][j][0] = acc[i][j][1] = acc[i][j][2] = acc[i][j][3] = 0.0f;
        {
            // The native GEMM's multistage order: a k-step's fragments read while the previous k-step's MMAs run, the
            // next stage's wait and barrier before a stage's last k-step, a stage's copies issued after its first.
            uint32_t a[2][MT][4], b[2][NT][2];
            kc::cp_async_wait<STAGES - 2>();
            __syncthreads();
            fragments(smem, 0, a[0], b[0]);
            for(int k_tile = 0; k_tile < KT; ++k_tile) {
                const unsigned char* stage = smem + (k_tile % STAGES) * C::kStage;
                const unsigned char* next = smem + ((k_tile + 1) % STAGES) * C::kStage;
#pragma unroll
                for(int ks = 0; ks < KB; ++ks) {
                    if(ks == KB - 1) {
                        kc::cp_async_wait<STAGES - 2>();
                        __syncthreads();
                        if(k_tile + 1 < KT) fragments(next, 0, a[(ks + 1) & 1], b[(ks + 1) & 1]);
                    } else {
                        fragments(stage, ks + 1, a[(ks + 1) & 1], b[(ks + 1) & 1]);
                    }
                    if(ks == 0) {
                        if(k_tile + STAGES - 1 < KT) issue(cur, k_tile + STAGES - 1);
                        kc::cp_async_commit();
                    }
#pragma unroll
                    for(int i = 0; i < MT; ++i)
#pragma unroll
                        for(int j = 0; j < NT; ++j)
                            kc::mma_e4m3_m16n8k32_fast(acc[i][j], a[ks & 1][i][0], a[ks & 1][i][1], a[ks & 1][i][2],
                                                       a[ks & 1][i][3], b[ks & 1][j][0], b[ks & 1][j][1]);
                }
            }
        }
        // The rank-1 scales of the lane's outputs: its tokens' activation scales, its rows' weight scales x post.
        float rs[MT][2], cs[NT][2];
#pragma unroll
        for(int i = 0; i < MT; ++i)
#pragma unroll
            for(int h = 0; h < 2; ++h) {
                const int t = wm0 + 16 * i + gid + 8 * h;
                rs[i][h] = t < cur.tokens ? __ldg(acts.scales + cur.token0 + std::size_t(t)) : 0.0f;
            }
#pragma unroll
        for(int j = 0; j < NT; ++j)
#pragma unroll
            for(int c = 0; c < 2; ++c) {
                const int r = wn0 + 8 * j + 2 * tig + c;
                cs[j][c] = r < cur.rows ? __fmul_rn(__ldg(w_scales + (cur.n0 + r) / m.scale_rows), m.post) : 0.0f;
            }
        const int next = linear + int(gridDim.x);
        const bool more = next < total;
        Tile nx;
        OUT* tile_out = out + cur.token0 * std::size_t(out_ld) + std::size_t(cur.n0);
        if constexpr(EPI == 0) {
            if(more) {
                __syncthreads();   // every warp's last reads of the ring are done
                set(nx, next);
                prologue(nx);
            }
            go::store_scaled<OUT>(acc, rs, cs, wm0, wn0, lane, tile_out, std::size_t(out_ld), cur.tokens, cur.rows);
        } else {
            constexpr int kChunk = go::staged_chunk<OUT>(TM, TN, C::kSmem);
            kc::cp_async_wait<0>();
            go::store_scaled_staged<OUT, TM, TN, MT, NT, kChunk, T>(acc, rs, cs, wm0, wn0, lane,
                                                                    reinterpret_cast<OUT*>(smem), tile_out,
                                                                    std::size_t(out_ld), cur.tokens, cur.rows, tid);
            if(more) {
                __syncthreads();   // every thread's reads of the staged rows are done
                set(nx, next);
                prologue(nx);
            }
        }
        if(!more) break;
        cur = nx;
        linear = next;
    }
    kc::cp_async_wait<0>();
}

// A job whose matrix or activations are not channel-scaled (channel_ok), contrary to the call's statement, gets NaN
// outputs.
template<int TM, int TN, int WM, int WN, int BK, int STAGES, int GROUP, int EPI, class OUT>
__global__ void __launch_bounds__(32 * WM * WN, 1)
    channel_kernel(const Matrix* matrices, const GemmJob* jobs, Acts acts, OUT* out, int out_ld) {
    using C = Channel<TM, TN, WM, WN, BK, STAGES>;
    extern __shared__ __align__(128) unsigned char channel_smem[];
    const GemmJob job = jobs[blockIdx.y];
    const Matrix m = matrices[job.matrix];
    const int tiles_m = (job.count + TM - 1) / TM, tiles_n = (m.rows + TN - 1) / TN;
    if(job.count <= 0 || int(blockIdx.x) >= tiles_m * tiles_n) return;
    if(!channel_ok(m, acts)) {
        if(blockIdx.x == 0)
            for(int i = int(threadIdx.x); i < job.count * m.rows; i += C::kThreads)
                out[std::size_t(job.first + i / m.rows) * std::size_t(out_ld) + std::size_t(i % m.rows)] =
                    crit::kcore::gemm_out::round_to<OUT>(__int_as_float(0x7fc00000));
        return;
    }
    channel_tiles<C, OUT, TM, TN, WM, BK, STAGES, EPI>(m, acts, job, tiles_m, tiles_n, GROUP, channel_smem, out, out_ld);
}

// ---------------------------------------------------------------------------------------------------- blocks GEMM

// The prompt GEMM of scales that change along K (structure gemm-native-blocks: an FP8 checkpoint's 128 x 128 FP32
// block scales against activations quantized per group, MXFP8 matrices against activations whose scales are not
// powers of two, any of the kernel's layouts but the channel GEMM's). A scale span is the run of 32-element blocks
// over which neither operand's scale changes (gcd of scale_k and the activation group; the whole K for an operand whose
// scale is constant along K): its MMAs sum in a span accumulator in the tensor cores (mma_fp8.cuh's fastest e4m3 MMA),
// then one FMA folds it into the output's FP32 sum times the span's activation scale x weight scale. An operand's
// scale that is constant along K (one a token, or scale_k == cols) is applied once in the epilogue instead (with
// post), rounded once to FP32 or BF16. The code ring, fragments and persistent grouped order are the channel GEMM's;
// the stage's scales go to a ring of STAGES + 1 slots (FP32 words, E8M0 bytes decoded in place by the threads that
// copied them), one slot more than the code ring so a slot a warp still folds from is never the one being refilled.
// Not the declared order, not row invariant; an output's sum depends on the span (the layout) and the configuration,
// not on the job's token count.
template<int TM, int TN, int WM, int WN, int BK, int STAGES>
struct Blocks {
    static constexpr int kThreads = 32 * WM * WN, kWTM = TM / WM, kWTN = TN / WN;
    static constexpr int kMT = kWTM / 16, kNT = kWTN / 8, kKB = BK / 32;
    static_assert(kWTM % 16 == 0 && kWTN % 16 == 0 && kMT >= 1, "warp tiles of whole 16-token, 16-row tiles");
    static_assert(BK == 64 || BK == 128, "64 or 128 bytes of K a stage");
    static_assert(STAGES >= 2, "a ring of two stages or more");
    static constexpr int kA = 0, kB = TM * BK, kStage = (TM + TN) * BK;
    static constexpr int kSlot = (TM + TN) * kKB * 4, kSlots = STAGES + 1;   // [TM][KB] then [TN][KB] FP32
    static constexpr int kScales = STAGES * kStage;
    static constexpr int kSmem = kScales + kSlots * kSlot;
    static constexpr int kItems = ((TM + TN) * kKB + kThreads - 1) / kThreads;   // a thread's scale words a stage
};

__host__ __device__ __forceinline__ int gcd_int(int a, int b) {
    while(b) {
        const int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

template<class C, class OUT, int TM, int TN, int WM, int BK, int STAGES, int EPI>
__device__ __forceinline__ void blocks_tiles(const Matrix& m, const Acts& acts, const GemmJob& job, int tiles_m,
                                             int tiles_n, int group, unsigned char* smem, OUT* out, int out_ld) {
    namespace kt = crit::kcore::tile;
    namespace go = crit::kcore::gemm_out;
    constexpr int T = C::kThreads, MT = C::kMT, NT = C::kNT, KB = C::kKB;
    const int tid = int(threadIdx.x), warp = tid / 32, lane = tid % 32, gid = lane >> 2, tig = lane & 3;
    const int wm0 = (warp % WM) * C::kWTM, wn0 = (warp / WM) * C::kWTN;
    const int K = m.cols, KT = (K + BK - 1) / BK, total = tiles_m * tiles_n, blocks = K / 32;
    const unsigned char* w_bytes = static_cast<const unsigned char*>(m.scales);
    const int w_ld = K / m.scale_k;
    // Which operand's scale changes along K, and the span of blocks over which neither does.
    const bool a_k = acts.lds != 1, w_k = m.scale_k != K;
    const int span = (a_k && w_k) ? gcd_int(acts.group, m.scale_k) / 32 : a_k ? acts.group / 32
                                                                            : w_k ? m.scale_k / 32 : blocks;
    // Weight scales in blocks of rows that hold a CTA's TN rows whole: one weight scale a stage block for the tile.
    const bool w_uniform = w_k && m.scale_rows % TN == 0;

    struct Tile {
        int n0, tokens, rows;
        std::size_t token0;
        kt::KTileCopy<TM, BK, T> a;
        kt::KTileCopy<TN, BK, T> b;
    };
    auto set = [&](Tile& s, int linear) {
        int tm, tn;
        kt::tile_of(linear, tiles_m, tiles_n, group, tm, tn);
        s.n0 = tn * TN;
        s.tokens = min(TM, job.count - tm * TM);
        s.rows = min(TN, m.rows - s.n0);
        s.token0 = std::size_t(job.first + tm * TM);
        s.a.init(acts.codes + s.token0 * std::size_t(acts.ld), std::size_t(acts.ld), s.tokens, tid);
        s.b.init(m.codes + std::size_t(s.n0) * std::size_t(K), std::size_t(K), s.rows, tid);
    };
    auto slot = [&](int k_tile) { return reinterpret_cast<float*>(smem + C::kScales + (k_tile % C::kSlots) * C::kSlot); };
    // Scale word i of [TM][KB] then [TN][KB] is thread i % T's; its source (floats for FP32, bytes for E8M0), or
    // nothing where that operand's scale is constant along K (the epilogue applies it) or past the tile.
    auto item = [&](const Tile& s, int i, int k0, bool& is_a, bool& ok) -> std::size_t {
        is_a = i < TM * KB;
        const int j = is_a ? i : i - TM * KB, row = j / KB, k = k0 + 32 * (j % KB);
        ok = (is_a ? a_k && row < s.tokens : w_k && row < s.rows) && k < K;
        if(!ok) return 0;
        return is_a ? (s.token0 + std::size_t(row)) * std::size_t(acts.lds) + std::size_t(k / acts.group)
                    : std::size_t((s.n0 + row) / m.scale_rows) * std::size_t(w_ld) + std::size_t(k / m.scale_k);
    };
    auto issue = [&](const Tile& s, int k_tile) {
        unsigned char* stage = smem + (k_tile % STAGES) * C::kStage;
        const int k0 = k_tile * BK;
        s.a.issue(stage + C::kA, k0, K);
        s.b.issue(stage + C::kB, k0, K);
        float* f = slot(k_tile);
#pragma unroll
        for(int u = 0; u < C::kItems; ++u) {
            const int i = tid + u * T;
            if(i >= (TM + TN) * KB || (i < TM * KB ? !a_k : !w_k)) continue;   // constant along K: never read
            bool is_a, ok;
            const std::size_t o = item(s, i, k0, is_a, ok);
            // past the tile or K: zero (an FP32 0, exponent byte 0: a harmless scale for the zero codes there)
            const void* src = !ok ? m.scales
                              : is_a ? static_cast<const void*>(acts.scales + o)
                              : m.scale_e8m0 ? static_cast<const void*>(w_bytes + (o & ~std::size_t(3)))
                                             : static_cast<const void*>(static_cast<const float*>(m.scales) + o);
            kc::cp_async_ca<4>(f + i, src, ok);
        }
    };
    // A landed slot's E8M0 words to FP32, in place, by the threads that copied them.
    auto prepare = [&](const Tile& s, int k_tile) {
        if(!m.scale_e8m0 || !w_k || k_tile >= KT) return;
        float* f = slot(k_tile);
        const int k0 = k_tile * BK;
#pragma unroll
        for(int u = 0; u < C::kItems; ++u) {
            const int i = tid + u * T;
            if(i < TM * KB || i >= (TM + TN) * KB) continue;
            bool is_a, ok;
            const std::size_t o = item(s, i, k0, is_a, ok);
            if(ok) f[i] = kc::e8m0_value(__float_as_uint(f[i]) >> (8 * (o & 3)));
        }
    };
    auto prologue = [&](const Tile& s) {
#pragma unroll
        for(int st = 0; st < STAGES - 1; ++st) {
            if(st < KT) issue(s, st);
            kc::cp_async_commit();
        }
    };
    auto fragments = [&](const unsigned char* stage, int ks, uint32_t (&a)[MT][4], uint32_t (&b)[NT][2]) {
#pragma unroll
        for(int i = 0; i < MT; ++i) kt::ldsm_a<BK>(stage + C::kA, wm0 + 16 * i, ks, lane, a[i]);
#pragma unroll
        for(int j = 0; j < NT; j += 2) {
            uint32_t four[4];
            kt::ldsm_b2<BK>(stage + C::kB, wn0 + 8 * j, ks, lane, four);
            b[j][0] = four[0], b[j][1] = four[1], b[j + 1][0] = four[2], b[j + 1][1] = four[3];
        }
    };

    // The fold factors of the span ending at block gb, from its stage's slot: an output's activation scale x weight
    // scale as fa (token) x fw (row); a uniform weight scale goes into fa, and a scale constant along K is 1 here.
    auto fold_scales = [&](int gb, float (&fa)[MT][2], float (&fw)[NT][2]) {
        const float* f = slot(gb / KB);
        const int e = gb % KB;
        const float w = w_uniform ? f[TM * KB + e] : 1.0f;
#pragma unroll
        for(int i = 0; i < MT; ++i)
#pragma unroll
            for(int h = 0; h < 2; ++h) fa[i][h] = (a_k ? f[(wm0 + 16 * i + gid + 8 * h) * KB + e] : 1.0f) * w;
#pragma unroll
        for(int j = 0; j < NT; ++j)
#pragma unroll
            for(int c = 0; c < 2; ++c)
                fw[j][c] = (w_k && !w_uniform) ? f[(TM + wn0 + 8 * j + 2 * tig + c) * KB + e] : 1.0f;
    };

    int linear = int(blockIdx.x);
    Tile cur;
    set(cur, linear);
    prologue(cur);
    for(;;) {
        float acc[MT][NT][4], part[MT][NT][4];
#pragma unroll
        for(int i = 0; i < MT; ++i)
#pragma unroll
            for(int j = 0; j < NT; ++j) acc[i][j][0] = acc[i][j][1] = acc[i][j][2] = acc[i][j][3] = 0.0f;
        {
            // Each span summed from zero in its own accumulator (the zero-accumulator form of the fast MMA on its
            // first block), folded into the output's sum with one FMA after its last block.
            uint32_t a[2][MT][4], b[2][NT][2];
            kc::cp_async_wait<STAGES - 2>();
            prepare(cur, 0);
            __syncthreads();
            fragments(smem, 0, a[0], b[0]);
            int left = span;   // blocks left in the current span
            for(int k_tile = 0; k_tile < KT; ++k_tile) {
                const unsigned char* stage = smem + (k_tile % STAGES) * C::kStage;
                const unsigned char* next = smem + ((k_tile + 1) % STAGES) * C::kStage;
#pragma unroll
                for(int ks = 0; ks < KB; ++ks) {
                    if(ks == KB - 1) {
                        kc::cp_async_wait<STAGES - 2>();
                        prepare(cur, k_tile + 1);
                        __syncthreads();
                        if(k_tile + 1 < KT) fragments(next, 0, a[(ks + 1) & 1], b[(ks + 1) & 1]);
                    } else {
                        fragments(stage, ks + 1, a[(ks + 1) & 1], b[(ks + 1) & 1]);
                    }
                    if(ks == 0) {
                        if(k_tile + STAGES - 1 < KT) issue(cur, k_tile + STAGES - 1);
                        kc::cp_async_commit();
                    }
                    const int g = k_tile * KB + ks;
                    if(left == span) {
#pragma unroll
                        for(int i = 0; i < MT; ++i)
#pragma unroll
                            for(int j = 0; j < NT; ++j)
                                kc::mma_e4m3_m16n8k32_fast_zero(part[i][j], a[ks & 1][i][0], a[ks & 1][i][1],
                                                                a[ks & 1][i][2], a[ks & 1][i][3], b[ks & 1][j][0],
                                                                b[ks & 1][j][1]);
                    } else {
#pragma unroll
                        for(int i = 0; i < MT; ++i)
#pragma unroll
                            for(int j = 0; j < NT; ++j)
                                kc::mma_e4m3_m16n8k32_fast(part[i][j], a[ks & 1][i][0], a[ks & 1][i][1],
                                                           a[ks & 1][i][2], a[ks & 1][i][3], b[ks & 1][j][0],
                                                           b[ks & 1][j][1]);
                    }
                    left = left == 1 ? span : left - 1;
                    if(g < blocks && (left == span || g + 1 == blocks)) {
                        float fa[MT][2], fw[NT][2];
                        fold_scales(g, fa, fw);
                        if(w_uniform || !w_k) {
#pragma unroll
                            for(int i = 0; i < MT; ++i)
#pragma unroll
                                for(int j = 0; j < NT; ++j)
#pragma unroll
                                    for(int e = 0; e < 4; ++e)
                                        acc[i][j][e] = fmaf(part[i][j][e], fa[i][e >> 1], acc[i][j][e]);
                        } else {
#pragma unroll
                            for(int i = 0; i < MT; ++i)
#pragma unroll
                                for(int j = 0; j < NT; ++j)
#pragma unroll
                                    for(int e = 0; e < 4; ++e)
                                        acc[i][j][e] = fmaf(part[i][j][e], fa[i][e >> 1] * fw[j][e & 1],
                                                            acc[i][j][e]);
                        }
                    }
                }
            }
        }
        // The scales constant along K, once: a token's activation scale, a row's weight scale x post.
        float rs[MT][2], cs[NT][2];
#pragma unroll
        for(int i = 0; i < MT; ++i)
#pragma unroll
            for(int h = 0; h < 2; ++h) {
                const int t = wm0 + 16 * i + gid + 8 * h;
                const float x = a_k ? 1.0f : t < cur.tokens ? __ldg(acts.scales + (cur.token0 + std::size_t(t)) *
                                                                                    std::size_t(acts.lds)) : 0.0f;
                rs[i][h] = x;
            }
#pragma unroll
        for(int j = 0; j < NT; ++j)
#pragma unroll
            for(int c = 0; c < 2; ++c) {
                const int r = wn0 + 8 * j + 2 * tig + c;
                float w = 1.0f;
                if(!w_k && r < cur.rows) {
                    const std::size_t o = std::size_t((cur.n0 + r) / m.scale_rows) * std::size_t(w_ld);
                    w = m.scale_e8m0 ? kc::e8m0_value(__ldg(w_bytes + o)) : __ldg(static_cast<const float*>(m.scales) + o);
                }
                cs[j][c] = __fmul_rn(w, m.post);
            }
        const int next = linear + int(gridDim.x);
        const bool more = next < total;
        Tile nx;
        OUT* tile_out = out + cur.token0 * std::size_t(out_ld) + std::size_t(cur.n0);
        if constexpr(EPI == 0) {
            if(more) {
                __syncthreads();   // every warp's last reads of the rings are done
                set(nx, next);
                prologue(nx);
            }
            go::store_scaled<OUT>(acc, rs, cs, wm0, wn0, lane, tile_out, std::size_t(out_ld), cur.tokens, cur.rows);
        } else {
            constexpr int kChunk = go::staged_chunk<OUT>(TM, TN, C::kSmem);
            kc::cp_async_wait<0>();
            go::store_scaled_staged<OUT, TM, TN, MT, NT, kChunk, T>(acc, rs, cs, wm0, wn0, lane,
                                                                    reinterpret_cast<OUT*>(smem), tile_out,
                                                                    std::size_t(out_ld), cur.tokens, cur.rows, tid);
            if(more) {
                __syncthreads();   // every thread's reads of the staged rows are done
                set(nx, next);
                prologue(nx);
            }
        }
        if(!more) break;
        cur = nx;
        linear = next;
    }
    kc::cp_async_wait<0>();
}

template<int TM, int TN, int WM, int WN, int BK, int STAGES, int GROUP, int EPI, class OUT>
__global__ void __launch_bounds__(32 * WM * WN, 1)
    blocks_kernel(const Matrix* matrices, const GemmJob* jobs, Acts acts, OUT* out, int out_ld) {
    using C = Blocks<TM, TN, WM, WN, BK, STAGES>;
    extern __shared__ __align__(128) unsigned char blocks_smem[];
    const GemmJob job = jobs[blockIdx.y];
    const Matrix m = matrices[job.matrix];
    const int tiles_m = (job.count + TM - 1) / TM, tiles_n = (m.rows + TN - 1) / TN;
    if(job.count <= 0 || int(blockIdx.x) >= tiles_m * tiles_n) return;
    blocks_tiles<C, OUT, TM, TN, WM, BK, STAGES, EPI>(m, acts, job, tiles_m, tiles_n, GROUP, blocks_smem, out, out_ld);
}

// ---------------------------------------------------------------------------------------------------- quantizer

// crit's quantize_group_device: MXFP8's 2^(floor(log2 amax) - 8) clamped to E8M0's range, or amax / 448; E4M3 by the
// hardware conversion (round to nearest even, saturating). An all-zero group: scale 1 (mx) or 0 (amax), zero codes.
__global__ void quantize_kernel(const void* x, int bf16, int ld_x, int rows, int cols, ScaleKind kind, Acts acts) {
    const int groups = cols / acts.group;
    const int i = int(blockIdx.x * blockDim.x + threadIdx.x);
    if(i >= rows * groups) return;
    const int row = i / groups, k0 = (i % groups) * acts.group;
    auto value = [&](int k) {
        const std::size_t at = std::size_t(row) * std::size_t(ld_x) + std::size_t(k0 + k);
        return bf16 ? __bfloat162float(static_cast<const __nv_bfloat16*>(x)[at]) : static_cast<const float*>(x)[at];
    };
    float amax = 0.0f;
    for(int k = 0; k < acts.group; ++k) amax = fmaxf(amax, fabsf(value(k)));
    float scale;
    if(kind == ScaleKind::mx) {
        int e = 0;
        (void)frexpf(amax, &e);
        int shared = amax > 0.0f ? e - 1 - 8 : 0;
        shared = shared < -127 ? -127 : shared > 127 ? 127 : shared;
        scale = ldexpf(1.0f, shared);
    } else {
        scale = __fdiv_rn(amax, 448.0f);
    }
    std::uint8_t* codes = const_cast<std::uint8_t*>(acts.codes) + std::size_t(row) * std::size_t(acts.ld) + std::size_t(k0);
    for(int k = 0; k < acts.group; ++k)
        codes[k] = scale > 0.0f
                       ? std::uint8_t(__nv_cvt_float_to_fp8(__fdiv_rn(value(k), scale), __NV_SATFINITE, __NV_E4M3))
                       : std::uint8_t(0);
    const_cast<float*>(acts.scales)[std::size_t(row) * std::size_t(acts.lds) + std::size_t(i % groups)] = scale;
}

bool bad_acts(const Acts& a) { return !a.codes || !a.scales || a.group <= 0 || a.group % kBlock || a.ld % 8; }

template<int kRowWarps, int kAhead, int STREAM>
void launch_rows(const Matrix* matrices, const RowJob* jobs, int job_count, int max_rows, const Acts& acts,
                 float* out, int out_ld, cudaStream_t stream) {
    const dim3 grid(unsigned((max_rows + 15) / 16), unsigned(job_count));
    kc::declared::fp8_rows_kernel<kRowWarps, kAhead, STREAM, kMaxJobTokens, Matrix, Acts, RowJob>
        <<<grid, 32 * kRowWarps, 0, stream>>>(matrices, jobs, acts, out, out_ld);
}

template<int kGemmWarps, int kTiles, int kUnroll>
void launch_gemm(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows, int max_count,
                 const Acts& acts, float* out, int out_ld, cudaStream_t stream) {
    const int tiles = (max_count + 8 * kTiles - 1) / (8 * kTiles);
    const dim3 grid(unsigned((max_rows + 16 * kGemmWarps - 1) / (16 * kGemmWarps)), unsigned(job_count),
                    unsigned(tiles < 65535 ? tiles : 65535));
    gemm_kernel<kGemmWarps, kTiles, kUnroll><<<grid, 32 * kGemmWarps, 0, stream>>>(matrices, jobs, acts, out, out_ld);
}

template<int BM, int BN, int WM, int WN, int G, int RUN, int STAGES>
cudaError_t launch_staged(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows, int max_count,
                          const Acts& acts, float* out, int out_ld, cudaStream_t stream) {
    using S = Staged<BM, BN, WM, WN, G, RUN, STAGES>;
    auto kernel = staged_kernel<BM, BN, WM, WN, G, RUN, STAGES>;
    static const cudaError_t attribute =
        cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, S::kSmem);
    if(attribute != cudaSuccess) {   // more shared memory than the device gives a CTA
        (void)cudaGetLastError();
        return attribute;
    }
    const int tiles = (max_count + BN - 1) / BN;
    const dim3 grid(unsigned((max_rows + BM - 1) / BM), unsigned(job_count), unsigned(tiles < 65535 ? tiles : 65535));
    kernel<<<grid, S::kThreads, S::kSmem, stream>>>(matrices, jobs, acts, out, out_ld);
    return cudaSuccess;
}

// Persistent CTAs: at most as many a job as the device holds at once (kernel at `threads` and `smem`), each taking
// tiles gridDim.x apart; cudaErrorInvalidValue past 2^31 tiles.
template<class KERNEL>
cudaError_t persistent_grid(KERNEL kernel, int threads, int smem, long long tiles, int job_count, dim3& grid) {
    static const int resident = [kernel, threads, smem] {
        int device = 0, sms = 0, per = 0;
        (void)cudaGetDevice(&device);
        (void)cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, device);
        (void)cudaOccupancyMaxActiveBlocksPerMultiprocessor(&per, kernel, threads, smem);
        (void)cudaGetLastError();
        return sms * (per > 0 ? per : 1);
    }();
    if(tiles > 0x7fffffffLL) return cudaErrorInvalidValue;
    grid = dim3{unsigned(tiles < resident ? tiles : resident), unsigned(job_count), 1u};
    return cudaSuccess;
}

template<int TM, int TN, int WM, int WN, int BK, int STAGES, int GROUP, int EPI, class OUT>
cudaError_t launch_channel(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows, int max_count,
                           const Acts& acts, OUT* out, int out_ld, cudaStream_t stream) {
    using C = Channel<TM, TN, WM, WN, BK, STAGES>;
    auto kernel = channel_kernel<TM, TN, WM, WN, BK, STAGES, GROUP, EPI, OUT>;
    static const cudaError_t attribute =
        cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, C::kSmem);
    if(attribute != cudaSuccess) {   // more shared memory than the device gives a CTA
        (void)cudaGetLastError();
        return attribute;
    }
    dim3 grid;
    const cudaError_t e = persistent_grid(kernel, C::kThreads, C::kSmem,
                                          (long long)((max_count + TM - 1) / TM) * ((max_rows + TN - 1) / TN),
                                          job_count, grid);
    if(e != cudaSuccess) return e;
    kernel<<<grid, C::kThreads, C::kSmem, stream>>>(matrices, jobs, acts, out, out_ld);
    return cudaSuccess;
}

template<int TM, int TN, int WM, int WN, int BK, int STAGES, int GROUP, int EPI, class OUT>
cudaError_t launch_blocks(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows, int max_count,
                          const Acts& acts, OUT* out, int out_ld, cudaStream_t stream) {
    using C = Blocks<TM, TN, WM, WN, BK, STAGES>;
