template<int TM, int TN, int WM, int WN, int BK, int STAGES, int GROUP, int EPI, bool NATIVE, class OUT>
cudaError_t launch_native(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows, int max_count,
                          const Acts& acts, OUT* out, int out_ld, cudaStream_t stream) {
    using C = Native<TM, TN, WM, WN, BK, STAGES, GROUP>;
    auto kernel = native_kernel<TM, TN, WM, WN, BK, STAGES, GROUP, EPI, NATIVE, OUT>;
    static const cudaError_t attribute =
        cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, C::kSmem);
    if(attribute != cudaSuccess) {   // more shared memory than the device gives a CTA
        (void)cudaGetLastError();
        return attribute;
    }
    // Persistent CTAs: at most as many a job as the device holds at once, each taking tiles gridDim.x apart.
    static const int resident = [kernel] {
        int device = 0, sms = 0, per = 0;
        (void)cudaGetDevice(&device);
        (void)cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, device);
        (void)cudaOccupancyMaxActiveBlocksPerMultiprocessor(&per, kernel, C::kThreads, C::kSmem);
        (void)cudaGetLastError();
        return sms * (per > 0 ? per : 1);
    }();
    const long long tiles = (long long)((max_count + TM - 1) / TM) * ((max_rows + TN - 1) / TN);
    if(tiles > 0x7fffffffLL) return cudaErrorInvalidValue;
    const dim3 grid{unsigned(tiles < resident ? tiles : resident), unsigned(job_count), 1u};
    kernel<<<grid, C::kThreads, C::kSmem, stream>>>(matrices, jobs, acts, out, out_ld);
    return cudaSuccess;
}

}  // namespace

cudaError_t enqueue_rows(const Matrix* matrices, const RowJob* jobs, int job_count, int max_rows, const Acts& acts,
                         float* out, int out_ld, cudaStream_t stream, int tokens) {
    if(!matrices || !jobs || job_count < 0 || max_rows < 0 || !out || bad_acts(acts)) return cudaErrorInvalidValue;
    if(job_count == 0 || max_rows == 0) return cudaSuccess;
    // The tuning's configuration for (max_rows, the activations' width) at `tokens`; every one gives the same bits.
    switch(crit_lookup_rows(max_rows, acts.ld, tokens)) {
#define CRIT_FP8_ROWS(index, warps, ahead, stream_codes) \
        case index: launch_rows<warps, ahead, stream_codes>(matrices, jobs, job_count, max_rows, acts, out, out_ld, \
                                                            stream); break;
        CRIT_CONFIGS_rows(CRIT_FP8_ROWS)
#undef CRIT_FP8_ROWS
        default: return cudaErrorInvalidConfiguration;
    }
    return cudaGetLastError();
}

cudaError_t enqueue_gemm(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows, int max_count,
                         const Acts& acts, float* out, int out_ld, cudaStream_t stream) {
    if(!matrices || !jobs || job_count < 0 || max_rows < 0 || max_count < 0 || !out || bad_acts(acts))
        return cudaErrorInvalidValue;
    if(job_count == 0 || max_rows == 0 || max_count == 0) return cudaSuccess;
    // The tuning's configuration for (max_rows, the activations' width) at max_count tokens; every one gives the same
    // bits.
    switch(crit_lookup_gemm(max_rows, acts.ld, max_count)) {
#define CRIT_FP8_GEMM(index, warps, tiles, unroll) \
        case index: launch_gemm<warps, tiles, unroll>(matrices, jobs, job_count, max_rows, max_count, acts, out, \
                                                      out_ld, stream); break;
        CRIT_CONFIGS_gemm(CRIT_FP8_GEMM)
#undef CRIT_FP8_GEMM
        default: return cudaErrorInvalidConfiguration;
    }
    return cudaGetLastError();
}

cudaError_t enqueue_gemm_staged(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows,
                                int max_count, const Acts& acts, float* out, int out_ld, cudaStream_t stream) {
    if(!matrices || !jobs || job_count < 0 || max_rows < 0 || max_count < 0 || !out || bad_acts(acts) ||
       acts.ld % 16 || reinterpret_cast<std::uintptr_t>(acts.codes) % 16)
        return cudaErrorInvalidValue;
    if(job_count == 0 || max_rows == 0 || max_count == 0) return cudaSuccess;
    // The tuning's configuration for (max_rows, the activations' width) at max_count tokens; every one gives the
    // declared order's bits, the same as enqueue_gemm's.
    cudaError_t e = cudaErrorInvalidConfiguration;
    switch(crit_lookup_gemm_staged(max_rows, acts.ld, max_count)) {
#define CRIT_FP8_STAGED(index, bm, bn, wm, wn, group, run, stages) \
        case index: e = launch_staged<bm, bn, wm, wn, group, run, stages>(matrices, jobs, job_count, max_rows, \
                                                                          max_count, acts, out, out_ld, stream); break;
        CRIT_CONFIGS_gemm_staged(CRIT_FP8_STAGED)
#undef CRIT_FP8_STAGED
        default: break;
    }
    return e != cudaSuccess ? e : cudaGetLastError();
}

namespace {
template<class OUT>
cudaError_t gemm_native_as(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows, int max_count,
                           const Acts& acts, bool mx, OUT* out, int out_ld, cudaStream_t stream) {
    if(!matrices || !jobs || job_count < 0 || max_rows < 0 || max_count < 0 || !out || bad_acts(acts) ||
       acts.ld % 16 || reinterpret_cast<std::uintptr_t>(acts.codes) % 16)
        return cudaErrorInvalidValue;
    if(job_count == 0 || max_rows == 0 || max_count == 0) return cudaSuccess;
    // Not MXFP8 throughout: the blocks GEMM (structure gemm-native-blocks), each scale span summed in the tensor
    // cores and folded with one FMA, its own tuning.
    if(!mx) {
        cudaError_t e = cudaErrorInvalidConfiguration;
        switch(crit_lookup_gemm_native_blocks(max_rows, acts.ld, max_count)) {
#define CRIT_FP8_BLOCKS(index, tm, tn, wm, wn, bk, stages, group, epi)             case index: e = launch_blocks<tm, tn, wm, wn, bk, stages, group, epi>(matrices, jobs, job_count,                                                                                   max_rows, max_count, acts, out,                                                                                   out_ld, stream);                 break;
            CRIT_CONFIGS_gemm_native_blocks(CRIT_FP8_BLOCKS)
#undef CRIT_FP8_BLOCKS
            default: break;
        }
        return e != cudaSuccess ? e : cudaGetLastError();
    }
    cudaError_t e = cudaErrorInvalidConfiguration;
    switch(crit_lookup_gemm_native(max_rows, acts.ld, max_count)) {
#define CRIT_FP8_NATIVE(index, tm, tn, wm, wn, bk, stages, group, epi)         case index: e = launch_native<tm, tn, wm, wn, bk, stages, group, epi, true>(matrices, jobs, job_count,                                                                                     max_rows, max_count, acts, out,                                                                                     out_ld, stream);             break;
        CRIT_CONFIGS_gemm_native(CRIT_FP8_NATIVE)
#undef CRIT_FP8_NATIVE
        default: break;
    }
    return e != cudaSuccess ? e : cudaGetLastError();
}

template<class OUT>
cudaError_t gemm_channel_as(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows, int max_count,
                            const Acts& acts, OUT* out, int out_ld, cudaStream_t stream) {
    if(!matrices || !jobs || job_count < 0 || max_rows < 0 || max_count < 0 || !out || !acts.codes || !acts.scales ||
       acts.lds != 1 || acts.ld % 16 || reinterpret_cast<std::uintptr_t>(acts.codes) % 16)
        return cudaErrorInvalidValue;
    if(job_count == 0 || max_rows == 0 || max_count == 0) return cudaSuccess;
    cudaError_t e = cudaErrorInvalidConfiguration;
    switch(crit_lookup_gemm_native_channel(max_rows, acts.ld, max_count)) {
#define CRIT_FP8_CHANNEL(index, tm, tn, wm, wn, bk, stages, group, epi)         case index: e = launch_channel<tm, tn, wm, wn, bk, stages, group, epi>(matrices, jobs, job_count, max_rows,                                                                                max_count, acts, out, out_ld, stream);             break;
        CRIT_CONFIGS_gemm_native_channel(CRIT_FP8_CHANNEL)
#undef CRIT_FP8_CHANNEL
        default: break;
    }
    return e != cudaSuccess ? e : cudaGetLastError();
}
}  // namespace

cudaError_t enqueue_gemm_native(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows,
                                int max_count, const Acts& acts, bool mx, float* out, int out_ld, cudaStream_t stream) {
    return gemm_native_as(matrices, jobs, job_count, max_rows, max_count, acts, mx, out, out_ld, stream);
}

cudaError_t enqueue_gemm_native(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows,
                                int max_count, const Acts& acts, bool mx, void* out, bool out_bf16, int out_ld,
                                cudaStream_t stream) {
    return out_bf16 ? gemm_native_as(matrices, jobs, job_count, max_rows, max_count, acts, mx,
                                     static_cast<__nv_bfloat16*>(out), out_ld, stream)
                    : gemm_native_as(matrices, jobs, job_count, max_rows, max_count, acts, mx,
                                     static_cast<float*>(out), out_ld, stream);
}

cudaError_t enqueue_gemm_native_channel(const Matrix* matrices, const GemmJob* jobs, int job_count, int max_rows,
                                        int max_count, const Acts& acts, void* out, bool out_bf16, int out_ld,
                                        cudaStream_t stream) {
#if defined(CRIT_SWEEP_BUILD)
    // A sweep build times the BF16 epilogue only (the bench's): half the instantiations to compile.
    if(!out_bf16) return cudaErrorNotSupported;
    return gemm_channel_as(matrices, jobs, job_count, max_rows, max_count, acts, static_cast<__nv_bfloat16*>(out),
                           out_ld, stream);
#else
    return out_bf16 ? gemm_channel_as(matrices, jobs, job_count, max_rows, max_count, acts,
                                      static_cast<__nv_bfloat16*>(out), out_ld, stream)
                    : gemm_channel_as(matrices, jobs, job_count, max_rows, max_count, acts,
                                      static_cast<float*>(out), out_ld, stream);
#endif
}

cudaError_t enqueue_quantize(const void* x, bool bf16, int ld_x, int rows, int cols, ScaleKind kind, const Acts& acts,
                             cudaStream_t stream) {
    if(!x || rows < 0 || cols < 0 || bad_acts(acts) || cols % acts.group) return cudaErrorInvalidValue;
    const int n = rows * (cols / acts.group);
    if(n == 0) return cudaSuccess;
    quantize_kernel<<<(n + 127) / 128, 128, 0, stream>>>(x, bf16 ? 1 : 0, ld_x, rows, cols, kind, acts);
    return cudaGetLastError();
}

